const fs = require('fs');
const path = require('path');
const crypto = require('crypto');


// --- bundled site files (gzipped + base64, unpacked into memory at startup) ---
const SITE = (() => {
  const zlib_ = require('zlib');
  const packed = {"index.html":"","range.html":"","shop.html":"","payment-result.html":"","404.html":"","assets/logo.png":"","assets/i18n.js":"","assets/p-tv.jpg":"","assets/p-receiver.jpg":"","assets/p-stove.jpg":"","assets/p-multiswitch.jpg":"","assets/ph-mount.svg":"","assets/ph-cable.svg":"","assets/ph-lnb.svg":"","assets/ph-finder.svg":"","assets/ph-kettle.svg":"","robots.txt":"H4sIAAAAAAACAwstTi3STUxPzSuxUtDicszJyS+3UtDnCs4sSc1NLLBSyCgpKSi20tcvLy/XKykqzU3MS81JTS4pys/LTC7WS87P1S+GKNWryM3hAgCA7941TgAAAA==","sitemap.xml":"H4sIAAAAAAACA02NTQ6CMBCF95yi6d4O7NQMdecJ9ACkjtCkP9gZBG5vMMS4enlf3peHlyUG9abCPqdWN6bWipLLD5/6Vt9v18NRX2yFUwlMopYYErd6EBnPAPM8G/ZCsRvZ5NIDu4Fix7BDqM1J20qpTbcYsrObybsqZYpdokBOSk7esXE5AsK2Qzd0qadnoZeNOckQVoQ/hmPxuXhZbWNqhF9D2K6qbzCJrT7+vCUo4QAAAA=="};
  const out = {};
  for (const k in packed) out[k] = zlib_.gunzipSync(Buffer.from(packed[k], 'base64'));
  return out;
})();

